import Mathlib

namespace BMO2025R2P3

def Board (n : ℕ) := Fin n → Fin n → Bool

def checkerboard (n : ℕ) : Board n :=
  fun i j => (i.val + j.val) % 2 = 0

inductive SwapOp (n : ℕ) where
  | row (i j : Fin n)
  | col (i j : Fin n)

def applyOp {n : ℕ} (op : SwapOp n) (b : Board n) : Board n :=
  match op with
  | .row i j => fun r c => if r = i then b j c else if r = j then b i c else b r c
  | .col i j => fun r c => if c = i then b r j else if c = j then b r i else b r c

def applyOps {n : ℕ} (ops : List (SwapOp n)) (b : Board n) : Board n :=
  ops.foldl (fun b op => applyOp op b) b

def ReachableFromCheckerboard (n : ℕ) (b : Board n) : Prop :=
  ∃ ops : List (SwapOp n), applyOps ops (checkerboard n) = b

def RestoreCost (n : ℕ) (b : Board n) : ℕ :=
  sInf { k : ℕ | ∃ ops : List (SwapOp n), ops.length = k ∧ applyOps ops b = checkerboard n }

def answer (n : ℕ) : ℕ :=
  if n % 2 = 0 then n / 2 else n - 1

def formalStatement : Prop :=
  ∀ n : ℕ, 0 < n →
    (∀ b : Board n, ReachableFromCheckerboard n b → RestoreCost n b ≤ answer n) ∧
    (∃ b : Board n, ReachableFromCheckerboard n b ∧ answer n ≤ RestoreCost n b)

end BMO2025R2P3
